import {formatValidationError, ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry schema compilation', () => {
  it('passes valid input and undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        inputs.push(input);
        return 'sunny';
      }
    );

    const input = {location: 'Paris', requestId: 'opaque'};
    await registry.execute('get_weather', input);

    expect(inputs).toEqual([input]);
  });

  it('compiles a static schema once across repeated executions', async () => {
    let schemaReads = 0;
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      get inputSchema() {
        schemaReads += 1;
        return inputSchema;
      },
    } as ToolDefinition;
    const registry = new ToolRegistry();

    registry.register(definition, async () => 'sunny');
    for (let call = 0; call < 10; call += 1) {
      await registry.execute('get_weather', {location: 'Paris'});
    }

    expect(schemaReads).toBe(1);
  });

  it('validates each function-valued definition against its current schema', async () => {
    const schemas = [
      {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
      {
        type: 'object',
        properties: {units: {enum: ['celsius', 'fahrenheit']}},
        required: ['units'],
      },
    ];
    let calls = 0;
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: schemas[Math.max(0, calls++ - 1) % schemas.length],
      }),
      async input => JSON.stringify(input)
    );

    const first = await registry.execute('get_weather', {location: 'Paris'});
    const second = await registry.execute('get_weather', {units: 'celsius'});

    expect([first.result, second.result]).toEqual([
      JSON.stringify({location: 'Paris'}),
      JSON.stringify({units: 'celsius'}),
    ]);
  });

  it('reports a wrong-typed property by path without the offending value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup', {identifier: 123456789});

    expect({
      executorCalls,
      result: response.result,
    }).toEqual({
      executorCalls: 0,
      result: 'Invalid input: /identifier must be string',
    });
  });

  it('reports a nested wrong-typed property by its full instance path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_lookup',
        description: 'Look up a nested record',
        inputSchema: {
          type: 'object',
          properties: {
            lookup: {
              type: 'object',
              properties: {identifier: {type: 'string'}},
            },
          },
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('nested_lookup', {lookup: {identifier: 123456789}});

    expect(response.result).toBe('Invalid input: /lookup/identifier must be string');
  });

  it('recovers a property path when the validator omits instancePath', () => {
    expect(
      formatValidationError({
        schemaPath: '#/properties/identifier/type',
        params: {type: 'string'},
        message: 'must be string',
      })
    ).toBe('/identifier must be string');
  });

  it('normalizes validator type wording to the public must form', () => {
    expect(
      formatValidationError({
        instancePath: '/identifier',
        message: 'should be string',
      })
    ).toBe('/identifier must be string');
  });
});
import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

interface ValidationErrorLike {
  instancePath?: unknown;
  dataPath?: unknown;
  schemaPath?: unknown;
  params?: unknown;
  message?: string;
  keyword?: string;
}

export function formatValidationError(error: ValidationErrorLike): string {
  const instancePath = typeof error.instancePath === 'string' ? error.instancePath : '';
  const dataPath = typeof error.dataPath === 'string' ? error.dataPath : '';
  const propertyPath =
    typeof error.schemaPath === 'string'
      ? [...error.schemaPath.matchAll(/\/properties\/([^/]+)/g)]
          .map(match => decodeSchemaPathSegment(match[1]))
          .join('/')
      : '';
  const path =
    instancePath ||
    dataPath.replace(/[[]['"]([^'"]+)["\]]/g, '/$1').replace(/\.([A-Za-z0-9_$-]+)/g, '/$1') ||
    (typeof error.params === 'object' && error.params !== null && 'missingProperty' in error.params
      ? `/${String(error.params.missingProperty)}`
      : propertyPath
        ? `/${propertyPath}`
        : '/');
  const message = error.message?.replace(/^should\b/, 'must');
  return `${path} ${message ?? error.keyword ?? 'schema validation failed'}`;
}

function decodeSchemaPathSegment(segment: string): string {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({
    strict: false,
    validateFormats: false,
    coerceTypes: false,
    useDefaults: false,
  } as ConstructorParameters<typeof Ajv>[0]);
  private readonly schemaValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  private compile(name: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      return this.validator.compile(schema);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Unable to compile inputSchema for tool ${name}: ${message}`, {cause: error});
    }
  }

  private validatorFor(name: string, schema: Record<string, unknown>): ValidateFunction {
    const cached = this.schemaValidators.get(schema);
    if (cached) return cached;
    const compiled = this.compile(name, schema);
    this.schemaValidators.set(schema, compiled);
    return compiled;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the registered schema; rejects invalid input and throws only for unknown tools (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator =
      tool.validator ?? this.validatorFor(name, this.resolveDefinition(tool.definitionSource).inputSchema);
    if (!validator(input)) {
      const errors = validator.errors?.map(formatValidationError) ?? ['input does not match the schema'];
      log.warn('tool', 'input rejected', {name, errors});
      return {result: `Invalid input: ${errors.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- A rejected type error identifies the property path and expected type without including the invalid value ([validated by rejects a wrong-typed property reports its field path without the offending value](../../src/orchestration/tools/registry.test.ts#L55)).
- A rejected nested type error identifies the full instance path and expected type ([validated by: reports a nested wrong-typed property by its full instance path](../../src/orchestration/tools/registry.test.ts#L117)).
- A rejected type error recovers the property path from validator metadata when an instance path is unavailable ([validated by: recovers a property path when the validator omits instancePath](../../src/orchestration/tools/registry.test.ts#L141)).
- Public rejection messages use `must` wording for type failures, even when the validator supplies legacy `should` wording ([validated by: normalizes validator type wording to the public must form](../../src/orchestration/tools/registry.test.ts#L151)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input and undeclared properties through unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L5)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L30)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each function-valued definition against its current schema](../../src/orchestration/tools/registry.test.ts#L55)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov

import {ToolRegistry} from './registry.js';
import {createChatOrchestrator} from '../chatOrchestrator.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {AIProvider, MessageChunk, SendMessageParams, ToolResultMessage} from '../../types/ai.js';
import type {ChatSession} from '../../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

describe('ToolRegistry inputSchema validation acceptance', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsRequiredField: true,
    });
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({
      executorCalls,
      mentionsField: response.result.includes('ssn'),
      mentionsExpectedType: response.result.includes('string'),
      leaksValueInResult: response.result.includes('123456789'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('123456789')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsExpectedType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      }),
      async input => {
        executorInputs.push(input);
        return `22C in ${String(input.location)}`;
      }
    );

    let firstRoundToolResult = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (round !== 2) {
          yield {type: 'text', text: '22C in Paris'};
          yield {type: 'stop', stopReason: 'end_turn'};
          return;
        }
        const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
        const firstContent = lastMessage.content[0];
        firstRoundToolResult = firstContent?.content ?? '';
        yield {
          type: 'tool_use',
          toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
        };
        yield {type: 'stop', stopReason: 'tool_use'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(
      provider,
      new PromptBuilder({identity: 'You are a test assistant.'}),
      registry
    );
    const session: ChatSession = {
      sessionId: 's-retry',
      userId: 'u1',
      entries: [{role: 'user', content: 'Weather in Paris?', timestamp: SENT_AT}],
    };

    const reply = await orchestrator.processMessage(session);

    expect({
      reply,
      executorInputs,
      firstAttemptRejectedForLocation:
        firstRoundToolResult.includes('location') && /required/i.test(firstRoundToolResult),
    }).toEqual({
      reply: '22C in Paris',
      executorInputs: [{location: 'Paris'}],
      firstAttemptRejectedForLocation: true,
    });
  });
});
